en:
//【小夏】
<voice name='小夏' class='小夏' src='voice/ma01/0150070b33'>
//「……」
"......"

//【雄飛】
<voice name='雄飛' class='雄飛' src='voice/ma01/0150080b56'>
//「警察なんかあてにならない。
