"Sabe..."

en:
//【雄飛】
<voice name='雄飛' class='雄飛' src='voice/ma01/0150210b56'>
//「うん」
"Yeah?"

pt:
//【雄飛】
<voice name='雄飛' class='雄飛' src='voice/ma01/0150210b56'>
