<voice name='小夏' class='小夏' src='voice/ma01/0150240b33'>
//「あ、えっと。そうじゃなくて。
//　そうじゃなくてね」
"Oh! That's not what I <br>meant!"

pt:
//【小夏】
<voice name='小夏' class='小夏' src='voice/ma01/0150240b33'>
//「あ、えっと。そうじゃなくて。
